3	// entries: AxisEntry[] = [{ system, signal, weight, counted }]
4	export function computeAxis(entries) {
5	  const weightedLean = entries.reduce((a, e) => a + e.weight * e.signal, 0);
6	  const resultPole = Math.abs(weightedLean) <= EPSILON ? 0 : Math.sign(weightedLean);
7	
8	  const counted = entries.filter(e => e.counted && Math.abs(e.signal) >= 0.5);
9	  const plus = counted.filter(e => e.signal > 0);
10	  const minus = counted.filter(e => e.signal < 0);
11	
12	  let contributing, dissenting;
13	  if (resultPole > 0) { contributing = plus; dissenting = minus; }
14	  else if (resultPole < 0) { contributing = minus; dissenting = plus; }
15	  else {
16	    [contributing, dissenting] = plus.length >= minus.length ? [plus, minus] : [minus, plus];
17	  }
18	
19	  let conflict = false;
20	  if (plus.length >= 1 && minus.length >= 1) {
21	    const massAll = entries.reduce((a, e) => a + Math.abs(e.weight * e.signal), 0);
22	    const minoritySide = contributing.length >= dissenting.length ? dissenting : contributing;
23	    const minMass = minoritySide.reduce((a, e) => a + Math.abs(e.weight * e.signal), 0);
24	    conflict = massAll > 0 && minMass / massAll >= CONFLICT_RATIO;
25	  }
26	
27	  return {
28	    resultPole,
29	    stars: contributing.length,
30	    conflict,
31	    contributingSystems: contributing.map(e => e.system),
32	    dissentingSystems: dissenting.map(e => e.system),
33	    weightedLean,
34	  };
35	}
