17	export function clustersToSignals(counts) {
18	  const out = {};
19	  for (const [axis, { plus, minus }] of Object.entries(AXIS_MEMBERS)) {
20	    const sum = keys => keys.reduce((a, k) => a + (counts[k] || 0), 0);
21	    out[axis] = diffToSignal(sum(plus) - sum(minus));
22	  }
23	  return out;
24	}
