40	export function tallyTenGods(birth) {
41	  const { year, month, day, hour, calendar } = birth;
42	  const timeUnknown = hour == null;
43	  const h = timeUnknown ? 12 : hour;
44	  const solar = calendar === 'lunar'
45	    ? Lunar.fromYmdHms(year, month, day, h, 0, 0).getSolar()
46	    : Solar.fromYmdHms(year, month, day, h, 0, 0);
47	  const ec = solar.getLunar().getEightChar();
48	
49	  const counts = EMPTY();
50	  addGod(counts, ec.getYearShiShenGan());
51	  addGod(counts, ec.getMonthShiShenGan());
52	  if (!timeUnknown) addGod(counts, ec.getTimeShiShenGan());
53	  const firstOf = arr => (arr && arr.length ? arr[0] : null);
54	  [ec.getYearShiShenZhi(), ec.getMonthShiShenZhi(), ec.getDayShiShenZhi()]
55	    .forEach(arr => { const g = firstOf(arr); if (g) addGod(counts, g); });
56	  if (!timeUnknown) { const g = firstOf(ec.getTimeShiShenZhi()); if (g) addGod(counts, g); }
57	
58	  return { counts, timeUnknown };
59	}
